            </div>
            <div>
              <p className="text-xs tracking-wider text-muted-foreground uppercase">
                Offene Punkte
              </p>
              <p className="mt-1 text-sm leading-relaxed text-foreground">{item.evidence.offen}</p>
            </div>
          </div>
        </div>
      </div>
