          <p className="mt-4 whitespace-pre-wrap font-serif text-lg leading-9 text-foreground">
            {item.text}
          </p>
        </div>

        <dl className="mt-7 grid gap-5 text-sm sm:grid-cols-2">
          <Detail label="Schuldner" value={item.schuldner} />
          <Detail
