  async function loadNewest(expectedUrl,godModeRun=false){const response=await api("/api/cases"),list=godModeRun?(response.god_mode_cases||[]):response.cases;const item=list.find(entry=>entry.requested_url===expectedUrl)||list.find(entry=>entry.url===expectedUrl)||list[0];if(!item)return;const data=await api(`/api/cases/${encodeURIComponent(item.case_id)}`);input.value=data.requested_url||data.url;renderArtifacts(data)}
