  function artifactMap(data){document.getElementById("evidence-warning").dataset.evidence_suitability=data.evidence_suitability||"";document.getElementById("package-download").textContent=data.god_mode?"Grey-Mode-Beweispaket herunterladen":"Beweispaket herunterladen";return new Map(data.artifacts.map(item=>[item.label,item]))}
