  function createDirectPill(title,available,onClick,infoText,status="available"){const wrap=document.createElement("span");wrap.className="pill-wrap"+(available?"":" unavailable")+(status==="warning"?" warning":"");const button=document.createElement("button");button.type="button";button.className="pill";button.disabled=!available;button.textContent=title;const info=document.createElement("button");info.type="button";info.className="info";info.textContent="i";info.dataset.info=infoText;info.setAttribute("aria-label",`Mehr Informationen zu ${title}`);if(available)button.addEventListener("click",onClick);wrap.append(button,info);pills.append(wrap);return wrap}
  function createMenuPill(title,items,infoText){const available=items.some(item=>item.available!==false);const wrap=document.createElement("span");wrap.className="pill-wrap"+(available?"":" unavailable");const button=document.createElement("button");button.type="button";button.className="pill";button.disabled=!available;button.textContent=`${title} ▾`;button.setAttribute("aria-haspopup","menu");button.setAttribute("aria-expanded","false");const menu=document.createElement("div");menu.className="pill-menu";menu.setAttribute("role","menu");menu.hidden=true;items.forEach(item=>{const child=document.createElement("button");child.type="button";child.setAttribute("role","menuitem");child.textContent=item.title;child.disabled=item.available===false;child.addEventListener("click",()=>{menu.hidden=true;button.setAttribute("aria-expanded","false");item.select(wrap)});menu.append(child)});const info=document.createElement("button");info.type="button";info.className="info";info.textContent="i";info.dataset.info=infoText;info.setAttribute("aria-label",`Mehr Informationen zu ${title}`);button.addEventListener("click",()=>{const open=menu.hidden;closePillMenus(menu);menu.hidden=!open;button.setAttribute("aria-expanded",String(open))});wrap.append(button,menu,info);pills.append(wrap);return wrap}
  function screenshotChoice(caseId,role,items){const labels={main:"screenshot",requested:"requested_page_screenshot",agb:"agb_screenshot",privacy:"privacy_screenshot"},gallery=galleries[role],item=items.get(labels[role]);if(gallery)return {title:gallery.title||role,available:true,select:wrap=>previewGallery(role,wrap,gallery.title||role)};if(item?.available)return {title:item.title,available:true,select:wrap=>preview(caseId,item,wrap)};return null}
  function renderArtifacts(data){trace.open=false;result.hidden=false;galleries=data.capture_galleries||{};document.getElementById("package-download").href=data.download_url||`/api/v1/cases/${encodeURIComponent(data.case_id)}/download`;pills.replaceChildren();const items=artifactMap(data),screenshots=roleOrder.map(role=>screenshotChoice(data.case_id,role,items)).filter(Boolean);const screenshotWrap=createMenuPill("Screenshots",screenshots,"Alle gesicherten Seitenansichten, getrennt nach Hauptseite und gefundenen Unterseiten.");const privacy=screenshotChoice(data.case_id,"privacy",items),privacyWrap=createDirectPill("Datenschutz-Screenshot",Boolean(privacy),()=>privacy.select(privacyWrap),help.privacy_screenshot,items.get("privacy_screenshot")?.status);const agb=screenshotChoice(data.case_id,"agb",items),agbWrap=createDirectPill("AGB-Screenshot",Boolean(agb),()=>agb.select(agbWrap),help.agb_screenshot,items.get("agb_screenshot")?.status);const texts=roleOrder.map(role=>{const gallery=galleries[role];if(!gallery?.normalized_text_url)return null;return {title:gallery.title||role,available:true,select:wrap=>previewRoleText(gallery,wrap)}}).filter(Boolean);if(!texts.length&&items.get("normalized_text")?.available){const item=items.get("normalized_text");texts.push({title:"Hauptseite",available:true,select:wrap=>preview(data.case_id,item,wrap)})}createMenuPill("Normalisierter Text",texts,"Bereinigter Text jeder erfassten Seite, getrennt nach Hauptseite, AGB und Datenschutz.");const documents=roleOrder.flatMap(role=>{const gallery=galleries[role];return (gallery?.document_urls||[]).map((url,index)=>({title:`${gallery.title||role} · Druckfassung ${index+1}`,available:true,select:wrap=>previewRoleDocument(url,gallery.title||role,wrap)}))});/* Druckfassungen liegen bewusst im Untermenü: createMenuPill("Druckfassungen" */const technical=[...documents,...data.artifacts.filter(item=>item.available&&!hiddenArtifacts.has(item.label)&&!primaryArtifacts.has(item.label)).sort((a,b)=>{const ai=technicalOrder.indexOf(a.label),bi=technicalOrder.indexOf(b.label);return (ai<0?999:ai)-(bi<0?999:bi)}).map(item=>({title:item.title,available:true,select:wrap=>preview(data.case_id,item,wrap)}))];createMenuPill("Technische Details",technical,"Technische Prüf- und Archivdateien für Sachverständige oder eine spätere Integritätskontrolle.");if(screenshots.length)screenshots[0].select(screenshotWrap);prepareCaseLinker(data)}
  function evidenceSubjectHost(value){const parsed=new URL(value);if(parsed.hostname!=="web.archive.org")return parsed.hostname;const match=parsed.pathname.match(/^\/web\/[^/]+\/(.+)$/i);if(!match)return parsed.hostname;try{const embedded=decodeURIComponent(match[1]),original=new URL(embedded);return /^https?:\/\//i.test(embedded)&&!original.username&&!original.password?original.hostname:parsed.hostname}catch(_){return parsed.hostname}}
  function monitoringUiUrl(path){return ["127.0.0.1","localhost"].includes(window.location.hostname)&&window.location.port==="8000"?`${window.location.protocol}//${window.location.hostname}:8080${path}`:path}
  function openMonitoringNotification(payload){const target=monitoringUiUrl("/hinweise");if(new URL(target,window.location.href).origin===window.location.origin){sessionStorage.setItem("muclegal:evidence-comparison-notification:v1",JSON.stringify(payload));window.location.assign(target);return}const url=new URL(target,window.location.href);url.searchParams.set("beweisvergleich",JSON.stringify(payload));window.location.assign(url)}
  async function prepareCaseLinker(data){caseLinker.hidden=false;currentEvidenceCaseId=data.case_id||"";matchingCases=new Map();baselineCase.replaceChildren(new Option("Fall auswählen",""));attachBaseline.textContent="Dem Fall zuordnen";attachBaseline.disabled=true;caseLinkerStatus.replaceChildren();if(data.god_mode){caseLinkerStatus.textContent="Grey-Mode-Pakete können nicht in die juristische Monitoringstrecke übernommen werden. Nutze für eigene oder synthetische Testseiten den regulären Modus, soweit der Abruf dort zulässig ist.";return}if(data.evidence_suitability&&data.evidence_suitability!=="regulaer"){caseLinkerStatus.textContent="Dieser Lauf ist nicht als regulärer Ausgangsbeweis geeignet.";return}try{const response=await api("/api/v1/monitoring-cases"),requestedHost=evidenceSubjectHost(data.requested_url||data.url),capturedHost=evidenceSubjectHost(data.captured_url||data.url);const cases=(response.cases||[]).filter(item=>{const allowed=new Set([item.domain,...(item.allowed_subdomains||[])]);return allowed.has(requestedHost)&&allowed.has(capturedHost)});cases.forEach(item=>{matchingCases.set(item.case_id,item);baselineCase.add(new Option(`${item.fall_id} · ${item.domain}${item.baseline_evidence?" · Ausgangsbeweis vorhanden":""}`,item.case_id))});if(!cases.length){caseLinkerStatus.textContent="Lege zuerst einen Monitoringfall für dieselbe Domain an.";const link=document.createElement("a");link.href="/neu";link.textContent=" Fall anlegen";caseLinkerStatus.append(link)}}catch(error){caseLinkerStatus.textContent=error.message}}
  baselineCase.addEventListener("change",()=>{const selected=matchingCases.get(baselineCase.value);attachBaseline.textContent=selected?.baseline_evidence?"Mit Ausgangsbeweis vergleichen":"Als Ausgangsbeweis zuordnen";attachBaseline.disabled=!selected||!currentEvidenceCaseId;caseLinkerStatus.textContent=""});
  attachBaseline.addEventListener("click",async()=>{const selected=matchingCases.get(baselineCase.value);if(!selected||!currentEvidenceCaseId)return;const isComparison=Boolean(selected.baseline_evidence),endpoint=isComparison?"evidence-comparisons":"baseline-evidence";attachBaseline.disabled=true;caseLinkerStatus.textContent=isComparison?"Beweise werden technisch verglichen …":"Zuordnung wird geprüft …";try{const response=await api(`/api/v1/cases/${encodeURIComponent(selected.case_id)}/${endpoint}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({evidence_case_id:currentEvidenceCaseId})});if(!isComparison){selected.baseline_evidence=response.baseline_evidence;attachBaseline.textContent="Mit Ausgangsbeweis vergleichen";caseLinkerStatus.replaceChildren(document.createTextNode(`Ausgangsbeweis ist ${response.fall_id} zugeordnet. `));const link=document.createElement("a");link.href=monitoringUiUrl("/hinweise");link.textContent="Fall öffnen";caseLinkerStatus.append(link);return}const comparison=response.comparison;if(comparison.status==="technische_aenderung_erkannt"){openMonitoringNotification({version:1,notification_id:comparison.comparison_id,case_id:response.case_id,fall_id:response.fall_id,status:comparison.status});return}caseLinkerStatus.replaceChildren(document.createTextNode(comparison.status==="unveraendert_fortbestehend"?"Kein technischer Unterschied zum Ausgangsbeweis erkannt. ":"Vergleich konnte nicht vollständig durchgeführt werden. "));const link=document.createElement("a");link.href=monitoringUiUrl("/hinweise");link.textContent="Fall öffnen";caseLinkerStatus.append(link)}catch(error){caseLinkerStatus.textContent=error.message;attachBaseline.disabled=false}});
  function resetViewer(){document.getElementById("empty").hidden=true;document.getElementById("text-view").hidden=true;document.getElementById("legal-view").hidden=true;document.getElementById("image-view").hidden=true;document.getElementById("pdf-view").hidden=true;document.getElementById("gallery-controls").hidden=true}
  async function preview(caseId,item,wrap){closePillMenus();setActive(wrap);resetViewer();document.getElementById("viewer-title").textContent=item.title;const open=document.getElementById("viewer-open"),info=document.getElementById("viewer-info"),fileUrl=item.url||`/artifact/${encodeURIComponent(caseId)}/${encodeURIComponent(item.label)}`;open.href=fileUrl;open.hidden=false;currentInfo=help[item.label]||item.title;info.dataset.info=currentInfo;info.hidden=false;if(item.kind==="image"){const roles={screenshot:"main",requested_page_screenshot:"requested",agb_screenshot:"agb",privacy_screenshot:"privacy"},gallery=galleries[roles[item.label]];if(gallery){showGallery(gallery);return}const image=document.getElementById("image-view");image.src=fileUrl;image.hidden=false;return}if(item.kind==="pdf"){const pdf=document.getElementById("pdf-view");pdf.src=fileUrl;pdf.hidden=false;return}if(item.kind==="text"&&item.preview_available){const content=item.preview_content!==undefined?item.preview_content:(await api(`/api/cases/${encodeURIComponent(caseId)}/preview/${encodeURIComponent(item.label)}`)).content;if(item.label==="legal_pages"){renderLegal(JSON.parse(content));return}const pre=document.getElementById("text-view");pre.textContent=content;pre.hidden=false;return}const empty=document.getElementById("empty");empty.textContent="Für dieses Dateiformat steht eine sichere Download-Datei bereit.";empty.hidden=false}
