  function showGallery(gallery){const images=gallery.tile_urls.length?gallery.tile_urls:(gallery.original_urls.length?gallery.original_urls:[gallery.preview_url]);let index=0;const image=document.getElementById("image-view"),controls=document.getElementById("gallery-controls"),counter=document.getElementById("tile-counter"),original=document.getElementById("tile-original"),prev=document.getElementById("tile-prev"),next=document.getElementById("tile-next");function show(){image.src=images[index];image.hidden=false;counter.textContent=`Kachel ${index+1}/${images.length}`;original.href=images[index];prev.disabled=index===0;next.disabled=index===images.length-1}prev.onclick=()=>{if(index>0){index--;show()}};next.onclick=()=>{if(index<images.length-1){index++;show()}};controls.hidden=false;show()}
