  const popover=document.getElementById("popover");function openInfo(button){popover.textContent=button.dataset.info||"Keine weitere Erklärung verfügbar.";popover.hidden=false;const rect=button.getBoundingClientRect();const left=Math.min(window.innerWidth-popover.offsetWidth-12,Math.max(12,rect.left));let top=rect.bottom+8;if(top+popover.offsetHeight>window.innerHeight-12)top=rect.top-popover.offsetHeight-8;popover.style.left=`${left}px`;popover.style.top=`${Math.max(12,top)}px`}
