  async function prepareCaseLinker(data){caseLinker.hidden=false;currentEvidenceCaseId=data.case_id||"";matchingCases=new Map();baselineCase.replaceChildren(new Option("Fall auswählen",""));attachBaseline.textContent="Dem Fall zuordnen";attachBaseline.disabled=true;caseLinkerStatus.replaceChildren();if(data.god_mode){caseLinkerStatus.textContent="Grey-Mode-Pakete können nicht in die juristische Monitoringstrecke übernommen werden. Nutze für eigene oder synthetische Testseiten den regulären Modus, soweit der Abruf dort zulässig ist.";return}if(data.evidence_suitability&&data.evidence_suitability!=="regulaer"){caseLinkerStatus.textContent="Dieser Lauf ist nicht als regulärer Ausgangsbeweis geeignet.";return}try{const response=await api("/api/v1/monitoring-cases"),requestedHost=evidenceSubjectHost(data.requested_url||data.url),capturedHost=evidenceSubjectHost(data.captured_url||data.url);const cases=(response.cases||[]).filter(item=>{const allowed=new Set([item.domain,...(item.allowed_subdomains||[])]);return allowed.has(requestedHost)&&allowed.has(capturedHost)});cases.forEach(item=>{matchingCases.set(item.case_id,item);baselineCase.add(new Option(`${item.fall_id} · ${item.domain}${item.baseline_evidence?" · Ausgangsbeweis vorhanden":""}`,item.case_id))});if(!cases.length){caseLinkerStatus.textContent="Lege zuerst einen Monitoringfall für dieselbe Domain an.";const link=document.createElement("a");link.href="/neu";link.textContent=" Fall anlegen";caseLinkerStatus.append(link)}}catch(error){caseLinkerStatus.textContent=error.message}}
